\section{Algorithmic summary}

\textbf{A1. Guarded-search compressor.} Input $y$, inverters $A_l$ for $f_l$,
fuel $F$. For $l=0,1,\dots,F(|y|)$: compute $p\leftarrow A_l(\one\cat y)$; if
$f_l(p)=\one\cat y$, output $p$. Correct by Theorem~\ref{thm:sfcorrect}; at most
$K_f(y)+1$ subroutine calls.

\textbf{A2. Prefix-oracle reconstruction.} Input $y$, oracle $\dect$, fuel $F$.
Find the least $n^\star\le F(|y|)$ with $\dect(y,\varepsilon,n^\star)$; then set
$w\leftarrow\varepsilon$ and repeat $n^\star$ times: append $\zero$ if
$\dect(y,w\cat\zero,\text{remaining}-1)$, else append $\one$. Output $w$. One
oracle call per output bit plus the length search.

\textbf{A3. Seed packaging.} Emit $|r|$ in unary, a separating $\zero$, then
$r\cat p$; the deterministic decompressor parses and calls $D_r(p)$. Overhead
$2|r|+1$ bits.

